type WorldState = Record<string, string>;

const initialState = (): WorldState => ({
  Osk: "nim",
  Fen: "nim",
});

const advanceEntity = (
  state: WorldState,
  entityDisplayName: "Osk" | "Fen"
): { success: true; newState: WorldState } | { success: false; error: string } => {
  if (state[entityDisplayName] !== "nim") {
    return {
      success: false,
      error: `${entityDisplayName} must be in nim before it can advance`,
    };
  }

  return {
    success: true,
    newState: { ...state, [entityDisplayName]: "pex" },
  };
};

export const protocol: WorldProtocol = {
  reset(): WorldState {
    return initialState();
  },

  applyOperation(state, operationDisplayName) {
    switch (operationDisplayName) {
      case "advanceOsk":
        return advanceEntity(state, "Osk");
      case "advanceFen":
        return advanceEntity(state, "Fen");
      case "advanceOskFen":
        if (state.Osk !== "nim" || state.Fen !== "nim") {
          return {
            success: false,
            error: "Osk and Fen must both be in nim before they can advance",
          };
        }
        return {
          success: true,
          newState: { ...state, Osk: "pex", Fen: "pex" },
        };
      default:
        return {
          success: false,
          error: `Unknown operation: ${operationDisplayName}`,
        };
    }
  },

  getEntityState(state, entityDisplayName) {
    return state[entityDisplayName] ?? "unknown";
  },

  toAbstractSnapshot(state) {
    return { ...state };
  },
};
"}],"workingNote":"protocol の公開メソッド形状を維持し、既存の個別 advance 操作に加えて advanceOskFen を追加しました。新操作は両エンティティが nim の場合のみ、入力状態を変更せず同時に pex へ遷移させます。"}

